    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;
    int n = bounds.size();

    for (int i = n - 1; i >= 0; i--) {
        if (i == n - 1) {
            suffixSumList.add(bounds.get(i));
        } else {
            suffixSumList.add(bounds.get(i) + suffixSumList.get(suffixSumList.size() - 1));
        }
